# ============================================================
# JAVASCRIPT
# ============================================================

JS = r"""
<script>
(function () {
    "use strict";

    function buildHeader() {

        var body = document.body;

        if (!body || document.querySelector(".momkn-header")) {
            return;
        }

        var generated =
            new Date().toLocaleString();

        var header = document.createElement("header");

        header.className = "momkn-header";

        header.innerHTML = `
            <div class="momkn-header-inner">

                <img
                    class="momkn-logo"
                    src="__LOGO_DATA_URI__"
                    alt="Al Ahly Momkn"
                >

                <div class="momkn-header-content">

                    <div class="momkn-eyebrow">
                        Security Engineering & DevSecOps
                    </div>

                    <h1 class="momkn-title">
                        DAST Security Assessment
                    </h1>

                    <div class="momkn-subtitle">
                        Dynamic Application Security Testing
                        &bull; OWASP ZAP Baseline Scan
                    </div>

                    <div class="momkn-meta">

                        <span class="momkn-pill">
                            OWASP ZAP
                        </span>

                        <span class="momkn-pill">
                            DAST
                        </span>

                        <span class="momkn-pill">
                            Automated Security Scan
                        </span>

                        <span class="momkn-pill">
                            Generated: ${generated}
                        </span>

                    </div>

                </div>

                <div class="momkn-badge">
                    DAST / ZAP
                </div>

            </div>
        `;

        body.insertBefore(
            header,
            body.firstChild
        );
    }


    function buildFooter() {

        var body = document.body;

        if (!body || document.querySelector(".momkn-footer")) {
            return;
        }

        var footer =
            document.createElement("footer");

        footer.className = "momkn-footer";

        footer.innerHTML = `
            <strong>Al Ahly Momkn</strong>
            &nbsp; | &nbsp;
            DevSecOps Security Platform
            &nbsp; | &nbsp;
            <span class="orange">OWASP ZAP</span>
            &nbsp; | &nbsp;
            DAST Assessment
        `;

        body.appendChild(footer);
    }


    function removeOldBranding() {

        /*
         * If this report was previously branded by an older
         * version of the script, remove the duplicate custom
         * blocks before adding the new design.
         */

        document
            .querySelectorAll(
                "#momkn-old-branding, .momkn-report-hero"
            )
            .forEach(function (element) {
                element.remove();
            });
    }


    document.addEventListener(
        "DOMContentLoaded",
        function () {

            removeOldBranding();

            buildHeader();

            buildFooter();
        }
    );

})();
</script>
"""


# ============================================================
# HTML HELPERS
# ============================================================

def inject_before_head_close(html, block):
    pattern = r"</head>"
    if re.search(pattern, html, re.I):
        return re.sub(
            pattern,
            block + "\n</head>",
            html,
            count=1,
            flags=re.I
        )

    return block + "\n" + html


def inject_before_body_close(html, block):
    pattern = r"</body>"
    if re.search(pattern, html, re.I):
        return re.sub(
            pattern,
            block + "\n</body>",
            html,
            count=1,
            flags=re.I
        )

    return html + "\n" + block


# ============================================================
# BRAND REPORT
# ============================================================

def brand_report(input_path, output_path):

    input_file = Path(input_path)
    output_file = Path(output_path)

    if not input_file.exists():
        raise FileNotFoundError(
            f"Input ZAP report not found: {input_file}"
        )

    html = input_file.read_text(
        encoding="utf-8",
        errors="replace"
    )

    now = datetime.now().strftime(
        "%Y-%m-%d %H:%M:%S"
    )

    # --------------------------------------------------------
    # Page title
    # --------------------------------------------------------

    title = (
        "Al Ahly Momkn | "
        "DAST Security Assessment | "
        "OWASP ZAP"
    )

    if re.search(
        r"<title>.*?</title>",
        html,
        re.I | re.S
    ):

        html = re.sub(
            r"<title>.*?</title>",
            f"<title>{title}</title>",
            html,
            count=1,
            flags=re.I | re.S
        )

    else:

        html = (
            f"<title>{title}</title>\n"
            + html
        )


    # --------------------------------------------------------
    # Prevent duplicate branding if report is processed again
    # --------------------------------------------------------

    html = re.sub(
        r"<!-- MOMKN-BRANDING-START -->.*?"
        r"<!-- MOMKN-BRANDING-END -->",
        "",
        html,
        flags=re.I | re.S
    )


    # --------------------------------------------------------
    # CSS
    # --------------------------------------------------------

    css_block = (
        "<!-- MOMKN-BRANDING-START -->\n"
        "<style>\n"
        + CSS
        + "\n</style>\n"
    )

    html = inject_before_head_close(
        html,
        css_block
    )


    # --------------------------------------------------------
    # JavaScript
    # --------------------------------------------------------

    js = JS.replace(
        "__LOGO_DATA_URI__",
        LOGO_DATA_URI
    )

    js += (
        f"\n<!-- Generated by Al Ahly Momkn "
        f"branding engine: {now} -->\n"
        "<!-- MOMKN-BRANDING-END -->"
    )

    html = inject_before_body_close(
        html,
        js
    )


    # --------------------------------------------------------
    # Write output
    # --------------------------------------------------------

    output_file.parent.mkdir(
        parents=True,
        exist_ok=True
    )

    output_file.write_text(
        html,
        encoding="utf-8"
    )

    print(
        "[brand_zap] "
        f"Generated: {output_file} "
        f"({output_file.stat().st_size:,} bytes)"
    )


# ============================================================
# CLI
# ============================================================

def main():

    if len(sys.argv) != 3:

        print(
            "Usage:\n"
            "  python3 brand_zap_report.py "
            "<input.html> <output.html>"
        )

        sys.exit(2)

    try:

        brand_report(
            sys.argv[1],
            sys.argv[2]
        )

    except Exception as exc:

        print(
            f"[brand_zap] ERROR: {exc}",
            file=sys.stderr
        )

        sys.exit(1)


if __name__ == "__main__":
    main()
